pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        address alice = address(0xaaa);
        address bob = address(0xbbb);
        MockToken token = new MockToken();
        address[] memory tos = new address[](2);
        tos[0] = alice;
        tos[1] = bob;
        uint v = 1;
        bool ok;
        try c.transfer(address(this), address(token), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

contract MockToken {
    uint public callCount;
    function transferFrom(address, address, uint) external returns (bool) {
        callCount++;
        if (callCount >= 2) {
            revert("second call fails");
        }
        return true;
    }
}
